            for i in range(right, left - 1, -1):
                if count == k:
                    return last
                last = mat[bottom][i]
                count += 1
            bottom -= 1

        # left column
        if left <= right:
            for i in range(bottom, top - 1, -1):
                if count == k:
                    return last
                last = mat[i][left]
                count += 1
            left += 1

